} from "@/components/ui/table";
import {
  autoMapCSVHeaders,
  createCSVSample,
  CSVImportError,
  executeImportAttempt,
  formatCSVError,
  importText,
  parseCSV,
  previewCSVImport,
  resolveCSVLimits,
  type CSVDocument,
  type CSVLimits,
  type ImportAttempt,
  type ImportCallback,
  type ImportField,
  type ImportKey,
  type ImportLocale,
  type ImportMapping,
  type ImportMode,
  type ImportProgress,
  type ImportResult,
  type ImportRowFailure,
  type ImportRowContext,
  type ImportValidation,
} from "@/lib/csv-import";
import { cn, downloadText } from "@/lib/utils";

export type ImportWizardProps<T extends object> = {
  fields: readonly ImportField<T>[];
  /** Commits belong to the caller. Abort/rejection must roll back this attempt. */
  onImport: ImportCallback<T>;
  locale?: ImportLocale;
  getRowKey?: (row: Readonly<T>) => ImportKey | null | undefined;
  /** Use the same normalization as getRowKey, e.g. lowercase customer emails. */
  existingKeys?: ReadonlySet<ImportKey> | readonly ImportKey[];
  validateRow?: (
    row: Readonly<T>,
    context: ImportRowContext,
  ) => ImportValidation;
  limits?: Partial<CSVLimits>;
  sampleRows?: readonly Partial<T>[];
  sampleFilename?: string;
  resourceHref?: string;
  title?: string;
  description?: string;
  className?: string;
};

type Step = 0 | 1 | 2 | 3;
type Phase =
  | "idle"
  | "importing"
  | "cancelling"
  | "complete"
  | "partial"
  | "cancelled"
  | "error"
  | "unverified";
type RowFilter = "all" | "invalid" | "duplicates";
const pageSize = 10;
const unmapped = "__unmapped__";

